"use strict";(self.webpackChunktmp_dmr_docu2=self.webpackChunktmp_dmr_docu2||[]).push([["3328"],{1754(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"3.0.0 (experimental)","banner":"unreleased","badge":true,"noIndex":false,"className":"docs-version-current","isLast":false,"docsSidebars":{"gettingStarted":[{"type":"link","href":"/DMR/3.0.0/getting-started/what-is-dmr","label":"What is DMR?","docId":"getting-started/what-is-dmr","unlisted":false},{"type":"link","href":"/DMR/3.0.0/getting-started/concepts","label":"Concepts","docId":"getting-started/concepts","unlisted":false},{"type":"link","href":"/DMR/3.0.0/getting-started/quickstart","label":"Hands-on Quickstart","docId":"getting-started/quickstart","unlisted":false},{"type":"link","href":"/DMR/3.0.0/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/DMR/3.0.0/getting-started/building-and-running","label":"Building and Running","docId":"getting-started/building-and-running","unlisted":false}],"userGuide":[{"type":"link","href":"/DMR/3.0.0/user-guide/app-structure","label":"Application Structure","docId":"user-guide/app-structure","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/reconfiguration-handling","label":"Reconfiguration Handling","docId":"user-guide/reconfiguration-handling","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/configuration","label":"Configuration","docId":"user-guide/configuration","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/analytics","label":"Analytics","docId":"user-guide/analytics","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/data-redistribution","label":"Data Redistribution","docId":"user-guide/data-redistribution","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/minidmr","label":"MiniDMR Local Cluster","docId":"user-guide/minidmr","unlisted":false},{"type":"category","label":"Policies","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/DMR/3.0.0/user-guide/policies/overview","label":"Overview","docId":"user-guide/policies/overview","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/policies/dmr-policies","label":"Built-in Policies","docId":"user-guide/policies/dmr-policies","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/policies/custom-policies","label":"Custom Policies","docId":"user-guide/policies/custom-policies","unlisted":false},{"type":"link","href":"/DMR/3.0.0/user-guide/policies/manual-control","label":"Manual Control","docId":"user-guide/policies/manual-control","unlisted":false}]},{"type":"link","href":"/DMR/3.0.0/user-guide/common-issues","label":"Common Issues","docId":"user-guide/common-issues","unlisted":false}],"api":[{"type":"link","href":"/DMR/3.0.0/api/core-api","label":"Core API","docId":"api/core-api","unlisted":false},{"type":"link","href":"/DMR/3.0.0/api/policy-headers","label":"Policy Headers","docId":"api/policy-headers","unlisted":false}],"examples":[{"type":"link","href":"/DMR/3.0.0/examples/hello-world","label":"Hello World","docId":"examples/hello-world","unlisted":false},{"type":"link","href":"/DMR/3.0.0/examples/distributed-dataset","label":"Distributed Dataset","docId":"examples/distributed-dataset","unlisted":false}],"references":[{"type":"link","href":"/DMR/3.0.0/references","label":"References","docId":"references","unlisted":false}]},"docs":{"api/core-api":{"id":"api/core-api","title":"Core API","description":"dmr.h is the only header an application needs to include. It is a barrel: it pulls in the whole public API and wraps it in extern \\"C\\" so C++ callers can use it directly.","sidebar":"api"},"api/policy-headers":{"id":"api/policy-headers","title":"Policy Headers","description":"dmrtestpolicies.h and dmrCEpolicy.h are the only headers an application includes by name besides dmr.h. They stay out of the barrel because the policies behind them are optional at build time, so what they declare depends on how DMR was compiled.","sidebar":"api"},"examples/distributed-dataset":{"id":"examples/distributed-dataset","title":"Distributed Dataset","description":"Shows how to manage a distributed dataset across dynamic reconfigurations.","sidebar":"examples"},"examples/hello-world":{"id":"examples/hello-world","title":"Hello World","description":"A minimal DMR application that shows how DMR reconfigurations work without transferring application data.","sidebar":"examples"},"getting-started/building-and-running":{"id":"getting-started/building-and-running","title":"Building and Running","description":"Once DMR is available on your system, you compile your application against it and launch it through the DMR wrapper. How you compile and launch depends on the mode of operation you target.","sidebar":"gettingStarted"},"getting-started/concepts":{"id":"getting-started/concepts","title":"Concepts","description":"This guide helps you evaluate whether DMR fits your application and walks through the key steps to integrate it.","sidebar":"gettingStarted"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"This page covers building DMR from source.","sidebar":"gettingStarted"},"getting-started/quickstart":{"id":"getting-started/quickstart","title":"Hands-on Quickstart","description":"The fastest way to try DMR locally is with MiniDMR, a CLI that spins up a Docker-based multi-node Slurm cluster in seconds, no HPC access required.","sidebar":"gettingStarted"},"getting-started/what-is-dmr":{"id":"getting-started/what-is-dmr","title":"What is DMR?","description":"Learn what DMR is, why it exists, and how it enables MPI applications to adapt resources at runtime in HPC systems.","sidebar":"gettingStarted"},"references":{"id":"references","title":"References","description":"Team","sidebar":"references"},"user-guide/analytics":{"id":"user-guide/analytics","title":"Analytics","description":"DMR can log structured analytics lines at each reconfiguration event. These logs can be visualized with the Jupyter notebook provided in viz/.","sidebar":"userGuide"},"user-guide/app-structure":{"id":"user-guide/app-structure","title":"Application Structure","description":"A DMR application is built around three lifecycle functions and a main loop. The central concept is that DMR returns a DMRAction value telling you what to do next, and DMR_AUTO handles the dispatch automatically.","sidebar":"userGuide"},"user-guide/common-issues":{"id":"user-guide/common-issues","title":"Common Issues","description":"Overlapping expands cause MPI launch failure","sidebar":"userGuide"},"user-guide/configuration":{"id":"user-guide/configuration","title":"Configuration","description":"DMR can be configured at compile time (CMake), at launch time (environment variables), and at runtime (setter functions). Environment variables override CMake defaults; runtime setters override environment variables.","sidebar":"userGuide"},"user-guide/data-redistribution":{"id":"user-guide/data-redistribution","title":"Data Redistribution","description":"When a reconfiguration happens, all processes exit and the executable restarts from scratch with the new process count. Before exiting, the old processes must transfer their state to the new ones so the application can resume correctly.","sidebar":"userGuide"},"user-guide/minidmr":{"id":"user-guide/minidmr","title":"MiniDMR Local Cluster","description":"MiniDMR is a CLI tool for creating and managing local Docker-based DMR clusters. It is the recommended way to run DMR locally for demos, development, and CI pipelines.","sidebar":"userGuide"},"user-guide/policies/custom-policies":{"id":"user-guide/policies/custom-policies","title":"Custom Policies","description":"A policy is any DMRPolicy struct whose callbacks you implement. There is nothing special about the built-ins: they use the same public interface your own policy does.","sidebar":"userGuide"},"user-guide/policies/dmr-policies":{"id":"user-guide/policies/dmr-policies","title":"Built-in Policies","description":"DMR ships three built-in policies. Each one is obtained from a constructor that returns a ready-to-use DMRPolicy *, which you hand to dmrsetpolicy.","sidebar":"userGuide"},"user-guide/policies/manual-control":{"id":"user-guide/policies/manual-control","title":"Manual Control","description":"Instead of registering a policy, your application can decide reconfiguration timing itself and pass SHOULDEXPAND, SHOULDSHRINK, or SHOULDSTAY to dmrcheck. This path does not touch the policy system at all: whatever you registered with dmrsetpolicy is ignored for that call.","sidebar":"userGuide"},"user-guide/policies/overview":{"id":"user-guide/policies/overview","title":"Overview","description":"A policy decides, on every iteration, whether the job should grow, shrink, or stay at its current size. In DMR a policy is a plain C object (DMRPolicy) that you register once with dmrsetpolicy, and that DMR evaluates whenever you call dmrcheck(USEPOLICY).","sidebar":"userGuide"},"user-guide/reconfiguration-handling":{"id":"user-guide/reconfiguration-handling","title":"Reconfiguration Handling","description":"DMR_AUTO dispatches to the right callback based on the DMRAction returned by a DMR function.","sidebar":"userGuide"}}}}')}}]);